pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize remaining space (Best Fit)
    let mut score = post;

    // Penalize creating "dead space" that is too small for common items (below 10) 
    // but too large to be ignored. We use a sigmoid-like penalty on post_residual.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, we penalize the bin
    // because it forces a new bin later.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Global state awareness: If we have many open bins, prioritize tightening the 
    // existing ones (lower mean_residual) to keep the packing dense.
    let density_penalty = (mean_residual - post) * (open_bins_count as f64 / 10.0);
    score += density_penalty;

    // Progression constraint: As we approach the end of the stream, prioritize 
    // filling existing bins aggressively to avoid leaving stragglers.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 5.0 * progress;
    }

    // New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), set a high baseline cost.
    // We only open a new bin if the existing fits are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        score = 45.0 + (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize bins that leave the smallest residual space.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin.
    // We want to leave just enough space for the next item to fit perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_gap) * 0.8;
    }

    // 3. New Bin Threshold: Discourage opening a new bin unless existing options are poor.
    // If bin_residual == bin_capacity, it's a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of current bins is already quite tight (< 15)
        // or if there are no other options (fitting_bins_count == 0).
        if mean_residual > 15.0 && fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // 4. Density Balancing: Favor bins that align with the current mean residual
    // to keep bin utilization uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Urgency factor: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post-residuals (Best Fit logic)
    let mut score = post;

    // Non-linear penalty for creating "fragmented" space (small, unusable residuals)
    // We heavily penalize post_residuals in the range (0, 10) as they are likely dead space
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead coupling: If the next item is large, avoid leaving a small residual
    // in the current bin that cannot accommodate it.
    if next_item_size > 0 {
        if post < next_item_size as f64 && post > 0.0 {
            score += (next_item_size as f64 - post) * 2.0;
        }
    }

    // Stream progression coupling: 
    // As the stream progresses, prioritize closing bins (lower mean_residual) 
    // to avoid leaving many half-empty bins at the end.
    score += (mean_residual * progress * 2.0);

    // New bin avoidance: 
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // scaled by the availability of other fitting bins to prevent premature bin opening.
    if bin_residual == bin_capacity {
        score += 25.0 + (fitting_bins_count as f64 * 15.0);
    }

    // Final refinement: penalize having too many open bins as the stream ends
    score += (open_bins_count as f64) * progress * 5.0;

    score
}

