    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow it if fitting_bins_count is low
    // to avoid fragmenting remaining space.
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalty for opening a new bin: proportional to how much space is currently wasted
        // in existing bins, scaled by progress to encourage tighter packing as the stream ends.
        score = (mean_residual * 0.5) + (1.0 - progress) * 40.0;

        // If we have very few bins, opening a new one is less penalized.
        if open_bins_count < 2 {
            score -= 15.0;
        }
    } else {
        // Prefer tight fits (Best-Fit principle).
        // post_residual^2 penalizes large gaps; we want post_residual close to 0.
        score = (post_residual as f64).powf(1.5);

        // Lookahead heuristic: if next_item_size is large, favor bins that can accommodate it.
        if next_item_size > 0 {
            let next_fits = (post_residual >= next_item_size) as i32 as f64;
            score -= next_fits * (next_item_size as f64 * 0.8);
        }

        // Avoid creating "unusable" tiny slivers (e.g., residual < 10) unless it's a perfect fit.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // If this is the only bin that can fit the item, prioritize it to avoid forcing a new bin.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // Dampen the effect of mean_residual as we approach the end of the stream.
    score += (mean_residual * progress);

    score
}

