pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual.
    // However, we penalize very tight fits (close to 0) if a lookahead item suggests 
    // we might need that space for a larger item later.
    if post_residual > 0 && post_residual < next_item_size {
        score += 50.0;
    }

    // 2. Penalty for opening a new bin:
    // Only open a new bin if the current mean_residual is very low, 
    // suggesting existing bins are already "fragmented".
