        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 100.0; // Heavily penalize opening new bins if we have space elsewhere.
        } else {
            score += 25.0; // Base cost to open a new bin.
        }
    }

    // 3. Dynamic Time Horizon:
    // As we approach the end of the stream, prioritize packing tightly to finish.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 4. Fitting Constraint:
    // If this is the ONLY bin that can fit the item, we must take it, 
    // unless the post_residual is extremely wasteful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global State Sensitivity:
    // If the mean residual is high, we have plenty of room; favor bins that 
    // keep the mean residual balanced.
    if mean_residual < 15.0 {
        score += post_residual as f64 * 0.5;
    }

    score
