pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement (Best Fit strategy).
    // We penalize small residuals that are too small to fit common future items (the "fragmentation" trap).
    let mut score = post;

    // Penalty for leaving a bin "nearly empty" early in the stream, 
    // but allow for more flexibility as the stream nears completion.
    if bin_residual == bin_capacity {
        // This is the cost of opening a new bin. 
        // We make it expensive early on, but cheaper as we run out of items.
        score = 25.0 + (progress * 50.0);
    } else {
        // Non-linear coupling: heavily penalize residuals that are small but unusable 
        // for the next item, scaled by how many other bins could fit this item.
        if next_item_size > 0 {
            if post < next_item_size as f64 {
                // If this placement makes it impossible to fit the lookahead item in this bin, 
                // penalize it unless we have many other fitting options.
                score += (next_item_size as f64 - post) * (1.0 + (1.0 / (fitting_bins_count as f64 + 1.0)));
            }
        }

        // Favor bins that align with the global mean residual to keep bin levels balanced.
        // This prevents creating "outlier" bins that are nearly full while others are empty.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Dynamic pressure: If fitting_bins_count is low, we are running out of options 
    // for this specific item; reward fitting it into existing bins.
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        score -= (1.0 / fitting_bins_count as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating 'dead space' that is too small for common items (below 10)
    // We penalize very small residuals (1-9) as they are likely to remain empty
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor larger post_residuals 
    // to accommodate the next item (Best Fit Decreasing style adaptation)
    if next_item_size > 0 {
        let lookahead_penalty = if post_residual < next_item_size {
            (next_item_size - post_residual) as f64 * 1.5
        } else {
            -(post_residual - next_item_size) as f64 * 0.5
        };
        score += lookahead_penalty;
    }

    // Dynamic thresholding: as the stream progresses, become more conservative 
    // about opening new bins. If this is a new bin (bin_residual == bin_capacity),
    // apply a penalty that scales with progress to force filling existing bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we approach the end of the stream
        score += 40.0 * (1.0 + progress);

        // If there are other bins that could fit this item, strongly discourage new bin
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Coupling with mean_residual: avoid bins that are significantly "emptier" than average
    // to keep the packing density concentrated.
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    score
}
